static NSString * const DGStateChanged = @"com.aosaid.deltaguard.state.changed";
static UIColor *DGBackground(void){ return [UIColor colorWithRed:.055 green:.055 blue:.075 alpha:1]; }
static UIColor *DGSurface(void){ return [UIColor colorWithRed:.11 green:.11 blue:.14 alpha:1]; }
static UIColor *DGText(void){ return [UIColor colorWithWhite:.94 alpha:1]; }
static UIColor *DGMuted(void){ return [UIColor colorWithWhite:.62 alpha:1]; }
static UIColor *DGPrimary(void){ return [UIColor colorWithRed:.16 green:.68 blue:.82 alpha:1]; }
static NSString *DGSelectedServer(void){ return [[NSUserDefaults standardUserDefaults] stringForKey:@"DGSelectedServer"] ?: @"com.tencent.tmgp.dfm"; }
static void DGLog(NSString *line){
    NSUserDefaults *d=[NSUserDefaults standardUserDefaults]; NSMutableArray *a=[[d arrayForKey:@"DGLog"] mutableCopy] ?: [NSMutableArray array];
    NSString *entry=[NSString stringWithFormat:@"%@ — %@", [[NSDate date] descriptionWithLocale:nil], line]; [a insertObject:entry atIndex:0]; if(a.count>80)[a removeObjectsInRange:NSMakeRange(80,a.count-80)]; [d setObject:a forKey:@"DGLog"]; [d synchronize]; [[NSNotificationCenter defaultCenter] postNotificationName:DGStateChanged object:nil];
}
static id DGWorkspace(void){ Class c=NSClassFromString(@"LSApplicationWorkspace"); if(!c)return nil; SEL s=NSSelectorFromString(@"defaultWorkspace"); if(![c respondsToSelector:s])return nil; return ((id(*)(id,SEL))objc_msgSend)(c,s); }
static NSArray *DGInstalledApplications(void){ id ws=DGWorkspace(); if(!ws)return @[]; SEL s=NSSelectorFromString(@"allApplications"); if(![ws respondsToSelector:s])return @[]; id apps=((id(*)(id,SEL))objc_msgSend)(ws,s); return [apps isKindOfClass:[NSArray class]]?apps:@[]; }
static BOOL DGHasBundle(NSString *bundleID){ for(id app in DGInstalledApplications()){ NSString *bid=[app valueForKey:@"applicationIdentifier"]; if([bid isEqualToString:bundleID])return YES; } return NO; }
static BOOL DGLaunchBundle(NSString *bundleID){ id ws=DGWorkspace(); SEL s=NSSelectorFromString(@"openApplicationWithBundleID:"); if(ws && [ws respondsToSelector:s]) return ((BOOL(*)(id,SEL,id))objc_msgSend)(ws,s,bundleID); return NO; }
static pid_t DGPIDForBundle(NSString *bundleID){
    if(!bundleID.length)return 0; id target=nil; for(id app in DGInstalledApplications()){ if([[app valueForKey:@"applicationIdentifier"] isEqualToString:bundleID]){target=app;break;} }
    NSString *path=nil; if(target){ id url=[target valueForKey:@"bundleURL"]; path=[url respondsToSelector:@selector(path)]?[url path]:nil; }
    if(!path.length)return 0; NSString *execName=nil; NSDictionary *info=[NSDictionary dictionaryWithContentsOfFile:[path stringByAppendingPathComponent:@"Info.plist"]]; execName=info[@"CFBundleExecutable"]; if(!execName.length)execName=bundleID.lastPathComponent;
    int bytes=proc_listpids(PROC_ALL_PIDS,0,NULL,0); if(bytes<=0)return 0; pid_t *pids=calloc((size_t)bytes,1); int used=proc_listpids(PROC_ALL_PIDS,0,pids,bytes); pid_t found=0;
    for(int i=0;i<used/(int)sizeof(pid_t);i++){ if(!pids[i])continue; char buf[PROC_PIDPATHINFO_MAXSIZE]={0}; if(proc_pidpath(pids[i],buf,sizeof(buf))>0){ NSString *p=[NSString stringWithUTF8String:buf]; if([p.lastPathComponent isEqualToString:execName] || [p hasPrefix:path]){found=pids[i];break;} } } free(pids); return found;
}
static NSDictionary *DGEnvironment(void){
    BOOL rootless=access("/var/jb",F_OK)==0; BOOL writable=access("/var/jb",W_OK)==0; BOOL workspace=DGWorkspace()!=nil; NSString *os=[UIDevice currentDevice].systemVersion; NSString *model=[UIDevice currentDevice].model;
    return @{ @"rootless":@(rootless), @"writable":@(writable), @"workspace":@(workspace), @"uid":@(getuid()), @"os":os ?: @"?", @"model":model ?: @"iPhone" };
}

@interface DGBaseViewController : UIViewController
@property(nonatomic,strong) UIScrollView *scroll; @property(nonatomic,strong) UIStackView *stack;
- (void)buildPage:(NSString *)title subtitle:(NSString *)subtitle; - (UIView *)card; - (UILabel *)label:(NSString *)text size:(CGFloat)size color:(UIColor *)color; - (UIButton *)button:(NSString *)title;
@end
@implementation DGBaseViewController
- (void)viewDidLoad{[super viewDidLoad];self.view.backgroundColor=DGBackground();self.view.semanticContentAttribute=UISemanticContentAttributeForceRightToLeft;}
- (void)buildPage:(NSString *)title subtitle:(NSString *)subtitle{ self.scroll=[UIScrollView new];self.scroll.alwaysBounceVertical=YES;self.scroll.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:self.scroll];[NSLayoutConstraint activateConstraints:@[[self.scroll.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor],[self.scroll.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[self.scroll.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor],[self.scroll.bottomAnchor constraintEqualToAnchor:self.view.bottomAnchor]]];self.stack=[UIStackView new];self.stack.axis=UILayoutConstraintAxisVertical;self.stack.spacing=14;self.stack.translatesAutoresizingMaskIntoConstraints=NO;[self.scroll addSubview:self.stack];[NSLayoutConstraint activateConstraints:@[[self.stack.topAnchor constraintEqualToAnchor:self.scroll.contentLayoutGuide.topAnchor constant:20],[self.stack.leadingAnchor constraintEqualToAnchor:self.scroll.frameLayoutGuide.leadingAnchor constant:20],[self.stack.trailingAnchor constraintEqualToAnchor:self.scroll.frameLayoutGuide.trailingAnchor constant:-20],[self.stack.bottomAnchor constraintEqualToAnchor:self.scroll.contentLayoutGuide.bottomAnchor constant:-28]]];UILabel *h=[self label:title size:28 color:DGText()];h.font=[UIFont systemFontOfSize:28 weight:UIFontWeightBold];[self.stack addArrangedSubview:h];if(subtitle.length){UILabel *s=[self label:subtitle size:13 color:DGMuted()];[self.stack addArrangedSubview:s];}}
- (UIView *)card{UIView *v=[UIView new];v.backgroundColor=DGSurface();v.layer.cornerRadius=16;return v;}
- (UILabel *)label:(NSString *)text size:(CGFloat)size color:(UIColor *)color{UILabel *l=[UILabel new];l.text=text;l.textColor=color;l.font=[UIFont systemFontOfSize:size];l.numberOfLines=0;l.textAlignment=NSTextAlignmentRight;l.adjustsFontForContentSizeCategory=YES;return l;}
- (UIButton *)button:(NSString *)title{UIButton *b=[UIButton buttonWithType:UIButtonTypeSystem];[b setTitle:title forState:UIControlStateNormal];[b setTitleColor:UIColor.whiteColor forState:UIControlStateNormal];b.backgroundColor=DGPrimary();b.layer.cornerRadius=13;b.titleLabel.font=[UIFont systemFontOfSize:16 weight:UIFontWeightSemibold];b.contentEdgeInsets=UIEdgeInsetsMake(14,16,14,16);return b;}
@end

@interface DGHomeViewController:DGBaseViewController@property(nonatomic,strong)UILabel *status;@property(nonatomic,strong)UILabel *log;@property(nonatomic,strong)UILabel *selected;@end
@implementation DGHomeViewController
- (void)viewDidLoad{[super viewDidLoad];[self buildPage:@"حارس ألعاب دلتا" subtitle:@"نسخة iOS أصلية — إدارة وتشغيل ومراقبة فعلية"];
 UIView *c=[self card];UIStackView *s=[UIStackView new];s.axis=UILayoutConstraintAxisVertical;s.spacing=8;s.layoutMargins=UIEdgeInsetsMake(18,18,18,18);s.layoutMarginsRelativeArrangement=YES;[s addArrangedSubview:[self label:@"حالة البيئة" size:13 color:DGMuted()]];self.status=[self label:@"" size:17 color:DGText()];self.status.font=[UIFont boldSystemFontOfSize:17];[s addArrangedSubview:self.status];self.selected=[self label:@"" size:13 color:DGMuted()];[s addArrangedSubview:self.selected];[c addSubview:s];s.translatesAutoresizingMaskIntoConstraints=NO;[NSLayoutConstraint activateConstraints:@[[s.topAnchor constraintEqualToAnchor:c.topAnchor],[s.bottomAnchor constraintEqualToAnchor:c.bottomAnchor],[s.leadingAnchor constraintEqualToAnchor:c.leadingAnchor],[s.trailingAnchor constraintEqualToAnchor:c.trailingAnchor]]];[self.stack addArrangedSubview:c];
 UIStackView *actions=[UIStackView new];actions.axis=UILayoutConstraintAxisHorizontal;actions.spacing=10;actions.distribution=UIStackViewDistributionFillEqually;UIButton *refresh=[self button:@"فحص الآن"];UIButton *launch=[self button:@"فتح الخادم"];[refresh addTarget:self action:@selector(refreshState) forControlEvents:UIControlEventTouchUpInside];[launch addTarget:self action:@selector(launchSelected) forControlEvents:UIControlEventTouchUpInside];[actions addArrangedSubview:refresh];[actions addArrangedSubview:launch];[self.stack addArrangedSubview:actions];
 UIButton *floating=[self button:@"تشغيل الأداة العائمة داخل التطبيق"];[floating addTarget:self action:@selector(showFloating) forControlEvents:UIControlEventTouchUpInside];[self.stack addArrangedSubview:floating];
 UIView *logCard=[self card];UIStackView *ls=[UIStackView new];ls.axis=UILayoutConstraintAxisVertical;ls.spacing=8;ls.layoutMargins=UIEdgeInsetsMake(16,16,16,16);ls.layoutMarginsRelativeArrangement=YES;UILabel *lh=[self label:@"سجل التشغيل" size:14 color:DGText()];lh.font=[UIFont boldSystemFontOfSize:14];[ls addArrangedSubview:lh];self.log=[self label:@"" size:12 color:DGMuted()];self.log.font=[UIFont monospacedSystemFontOfSize:11 weight:UIFontWeightRegular];[ls addArrangedSubview:self.log];UIStackView *lr=[UIStackView new];lr.axis=UILayoutConstraintAxisHorizontal;UIButton *copy=[self button:@"نسخ السجل"];UIButton *clear=[self button:@"مسح السجل"];copy.titleLabel.font=clear.titleLabel.font=[UIFont systemFontOfSize:13];[copy addTarget:self action:@selector(copyLog) forControlEvents:UIControlEventTouchUpInside];[clear addTarget:self action:@selector(clearLog) forControlEvents:UIControlEventTouchUpInside];[lr addArrangedSubview:copy];[lr addArrangedSubview:clear];[ls addArrangedSubview:lr];[logCard addSubview:ls];ls.translatesAutoresizingMaskIntoConstraints=NO;[NSLayoutConstraint activateConstraints:@[[ls.topAnchor constraintEqualToAnchor:logCard.topAnchor],[ls.bottomAnchor constraintEqualToAnchor:logCard.bottomAnchor],[ls.leadingAnchor constraintEqualToAnchor:logCard.leadingAnchor],[ls.trailingAnchor constraintEqualToAnchor:logCard.trailingAnchor]]];[self.stack addArrangedSubview:logCard];[[NSNotificationCenter defaultCenter]addObserver:self selector:@selector(refreshState) name:DGStateChanged object:nil];[self refreshState];}
- (void)refreshState{NSDictionary *e=DGEnvironment();NSString *server=DGSelectedServer();BOOL installed=DGHasBundle(server);pid_t pid=DGPIDForBundle(server);self.status.text=[NSString stringWithFormat:@"Rootless: %@  |  UID: %@\nالخادم: %@\nالتطبيق: %@%@",[e[@"rootless"]boolValue]?@"مكتشف":@"غير مكتشف",e[@"uid"],server,installed?@"مثبت":@"غير مثبت",pid?[NSString stringWithFormat:@" — يعمل PID %d",pid]:@" — غير مشغل"];self.status.textColor=([e[@"rootless"]boolValue]&&installed)?[UIColor systemGreenColor]:[UIColor systemOrangeColor];self.selected.text=[NSString stringWithFormat:@"iOS %@ — %@ — %@",e[@"os"],e[@"model"],[e[@"workspace"]boolValue]?@"كتالوج التطبيقات متاح":@"كتالوج التطبيقات غير متاح"];NSArray *a=[[NSUserDefaults standardUserDefaults]arrayForKey:@"DGLog"]?:@[];self.log.text=a.count?[a componentsJoinedByString:@"\n"]:@"لا توجد أحداث بعد.";}
- (void)launchSelected{NSString *bid=DGSelectedServer();DGLog([NSString stringWithFormat:@"طلب تشغيل %@",bid]);if(!DGLaunchBundle(bid)){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"تعذر التشغيل" message:@"التطبيق غير مثبت أو رفض النظام فتحه." preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"حسنًا" style:UIAlertActionStyleDefault handler:nil]];[self presentViewController:a animated:YES completion:nil];}dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(.6*NSEC_PER_SEC)),dispatch_get_main_queue(),^{[self refreshState];});}
- (void)copyLog{[UIPasteboard generalPasteboard].string=self.log.text;DGLog(@"تم نسخ السجل");}
- (void)clearLog{[[NSUserDefaults standardUserDefaults]removeObjectForKey:@"DGLog"];DGLog(@"تم مسح السجل");[self refreshState];}
- (void)showFloating{UIView *overlay=[UIView new];overlay.tag=913;overlay.backgroundColor=[DGSurface() colorWithAlphaComponent:.98];overlay.layer.cornerRadius=18;overlay.layer.borderWidth=1;overlay.layer.borderColor=[DGPrimary() colorWithAlphaComponent:.7].CGColor;overlay.translatesAutoresizingMaskIntoConstraints=NO;UILabel *t=[self label:@"أداة دلتا العائمة" size:17 color:DGText()];t.font=[UIFont boldSystemFontOfSize:17];UIButton *close=[self button:@"إغلاق"];UIButton *scan=[self button:@"فحص العملية"];UIButton *open=[self button:@"فتح الخادم"];[close addTarget:self action:@selector(removeFloating:) forControlEvents:UIControlEventTouchUpInside];[scan addTarget:self action:@selector(refreshState) forControlEvents:UIControlEventTouchUpInside];[open addTarget:self action:@selector(launchSelected) forControlEvents:UIControlEventTouchUpInside];UIStackView *s=[UIStackView new];s.axis=UILayoutConstraintAxisVertical;s.spacing=10;s.layoutMargins=UIEdgeInsetsMake(16,16,16,16);s.layoutMarginsRelativeArrangement=YES;[s addArrangedSubview:t];[s addArrangedSubview:scan];[s addArrangedSubview:open];[s addArrangedSubview:close];[overlay addSubview:s];s.translatesAutoresizingMaskIntoConstraints=NO;[NSLayoutConstraint activateConstraints:@[[s.topAnchor constraintEqualToAnchor:overlay.topAnchor],[s.bottomAnchor constraintEqualToAnchor:overlay.bottomAnchor],[s.leadingAnchor constraintEqualToAnchor:overlay.leadingAnchor],[s.trailingAnchor constraintEqualToAnchor:overlay.trailingAnchor]]];[self.view addSubview:overlay];[NSLayoutConstraint activateConstraints:@[[overlay.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor constant:22],[overlay.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor constant:-22],[overlay.bottomAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.bottomAnchor constant:-18]]];DGLog(@"تم فتح الأداة العائمة داخل DeltaGuard");}
