@end

@interface DGPermissionViewController:DGBaseViewController@property(nonatomic,strong)UILabel *state;@end
@implementation DGPermissionViewController
- (void)viewDidLoad{[super viewDidLoad];[self buildPage:@"إدارة الصلاحيات" subtitle:@"فحص حقيقي لبيئة iOS والجلبريك — بدون صلاحيات Android وهمية"];UIView *c=[self card];UIStackView *s=[UIStackView new];s.axis=UILayoutConstraintAxisVertical;s.spacing=10;s.layoutMargins=UIEdgeInsetsMake(18,18,18,18);s.layoutMarginsRelativeArrangement=YES;[s addArrangedSubview:[self label:@"الفحوصات الفعلية" size:14 color:DGText()]];for(NSString *x in [self checks]){[s addArrangedSubview:[self label:x size:15 color:DGMuted()]];}[c addSubview:s];s.translatesAutoresizingMaskIntoConstraints=NO;[NSLayoutConstraint activateConstraints:@[[s.topAnchor constraintEqualToAnchor:c.topAnchor],[s.bottomAnchor constraintEqualToAnchor:c.bottomAnchor],[s.leadingAnchor constraintEqualToAnchor:c.leadingAnchor],[s.trailingAnchor constraintEqualToAnchor:c.trailingAnchor]]];[self.stack addArrangedSubview:c];self.state=[self label:@"" size:15 color:DGText()];[self.stack addArrangedSubview:self.state];UIButton *refresh=[self button:@"إعادة الفحص"];[refresh addTarget:self action:@selector(refresh) forControlEvents:UIControlEventTouchUpInside];[self.stack addArrangedSubview:refresh];}
- (NSArray *)checks{NSDictionary *e=DGEnvironment();return @[[NSString stringWithFormat:@"Rootless: %@",[e[@"rootless"]boolValue]?@"مكتشف — /var/jb متاح":@"غير مكتشف"],[NSString stringWithFormat:@"صلاحية الكتابة في Rootless: %@",[e[@"writable"]boolValue]?@"متاحة":@"غير متاحة"],[NSString stringWithFormat:@"كتالوج التطبيقات: %@",[e[@"workspace"]boolValue]?@"متاح":@"غير متاح"],[NSString stringWithFormat:@"صلاحية التطبيق الحالي: UID %@ — تخزينه الخاص متاح",e[@"uid"]]];}
- (void)refresh{self.state.text=[self.checks componentsJoinedByString:@"\n"];self.state.textColor=[UIColor systemGreenColor];DGLog(@"تم فحص صلاحيات وبيئة iOS");}
@end

@interface DGServerViewController:DGBaseViewController@property(nonatomic,strong)UILabel *selected;@end
@implementation DGServerViewController
- (void)viewDidLoad{[super viewDidLoad];[self buildPage:@"اختيار الخادم" subtitle:@"يتحقق DeltaGuard من وجود التطبيق ويستطيع تشغيله فعليًا"];UIView *c=[self card];UIStackView *s=[UIStackView new];s.axis=UILayoutConstraintAxisVertical;s.spacing=8;s.layoutMargins=UIEdgeInsetsMake(8,0,8,0);s.layoutMarginsRelativeArrangement=YES;NSDictionary *servers=@{@"الخادم الصيني\ncom.tencent.tmgp.dfm":@"com.tencent.tmgp.dfm",@"الخادم الدولي\ncom.proxima.dfm":@"com.proxima.dfm",@"الخادم التايواني\ncom.garena.game.df":@"com.garena.game.df"};for(NSString *title in servers){UIButton *b=[self button:title];b.backgroundColor=UIColor.clearColor;[b setTitleColor:DGText() forState:UIControlStateNormal];b.contentHorizontalAlignment=UIControlContentHorizontalAlignmentRight;b.contentEdgeInsets=UIEdgeInsetsMake(15,20,15,20);b.accessibilityIdentifier=servers[title];[b addTarget:self action:@selector(selectServer:) forControlEvents:UIControlEventTouchUpInside];[s addArrangedSubview:b];} [c addSubview:s];s.translatesAutoresizingMaskIntoConstraints=NO;[NSLayoutConstraint activateConstraints:@[[s.topAnchor constraintEqualToAnchor:c.topAnchor],[s.bottomAnchor constraintEqualToAnchor:c.bottomAnchor],[s.leadingAnchor constraintEqualToAnchor:c.leadingAnchor],[s.trailingAnchor constraintEqualToAnchor:c.trailingAnchor]]];[self.stack addArrangedSubview:c];self.selected=[self label:@"" size:15 color:DGMuted()];[self.stack addArrangedSubview:self.selected];[self refresh];}
- (void)selectServer:(UIButton *)b{[[NSUserDefaults standardUserDefaults]setObject:b.accessibilityIdentifier forKey:@"DGSelectedServer"];[[NSUserDefaults standardUserDefaults]synchronize];DGLog([NSString stringWithFormat:@"تم اختيار الخادم %@",b.accessibilityIdentifier]);[self refresh];}
- (void)refresh{NSString *bid=DGSelectedServer();self.selected.text=[NSString stringWithFormat:@"المحدد: %@\nالحالة: %@",bid,DGHasBundle(bid)?@"التطبيق مثبت":@"غير مثبت على الجهاز"];self.selected.textColor=DGHasBundle(bid)?[UIColor systemGreenColor]:[UIColor systemOrangeColor];}
@end

@interface DGSettingsViewController:DGBaseViewController@property(nonatomic,strong)UISwitch *dark;@end
@implementation DGSettingsViewController
- (void)viewDidLoad{[super viewDidLoad];[self buildPage:@"الإعدادات" subtitle:@"إعدادات DeltaGuard الفعلية على iOS"];UIView *c=[self card];UIStackView *s=[UIStackView new];s.axis=UILayoutConstraintAxisVertical;s.spacing=8;s.layoutMargins=UIEdgeInsetsMake(14,18,14,18);s.layoutMarginsRelativeArrangement=YES;UIStackView *row=[UIStackView new];row.axis=UILayoutConstraintAxisHorizontal;UILabel *l=[self label:@"الوضع الداكن داخل التطبيق" size:16 color:DGText()];self.dark=[UISwitch new];self.dark.on=![[NSUserDefaults standardUserDefaults]objectForKey:@"DGDark"]||[[NSUserDefaults standardUserDefaults]boolForKey:@"DGDark"];[self.dark addTarget:self action:@selector(toggleDark:) forControlEvents:UIControlEventValueChanged];[row addArrangedSubview:l];[row addArrangedSubview:self.dark];[s addArrangedSubview:row];for(NSString *title in @[@"مسح سجل DeltaGuard",@"مسح كاش DeltaGuard",@"معلومات البيئة",@"التعليمات"]){UIButton *b=[self button:title];b.backgroundColor=UIColor.clearColor;[b setTitleColor:DGText() forState:UIControlStateNormal];b.contentHorizontalAlignment=UIControlContentHorizontalAlignmentRight;[b addTarget:self action:@selector(action:) forControlEvents:UIControlEventTouchUpInside];[s addArrangedSubview:b];}UILabel *v=[self label:@"الإصدار 0.2.0 — iOS native functional layer" size:13 color:DGMuted()];[s addArrangedSubview:v];[c addSubview:s];s.translatesAutoresizingMaskIntoConstraints=NO;[NSLayoutConstraint activateConstraints:@[[s.topAnchor constraintEqualToAnchor:c.topAnchor],[s.bottomAnchor constraintEqualToAnchor:c.bottomAnchor],[s.leadingAnchor constraintEqualToAnchor:c.leadingAnchor],[s.trailingAnchor constraintEqualToAnchor:c.trailingAnchor]]];[self.stack addArrangedSubview:c];}
- (void)toggleDark:(UISwitch *)sw{[[NSUserDefaults standardUserDefaults]setBool:sw.isOn forKey:@"DGDark"];DGLog(sw.isOn?@"تم تفعيل الوضع الداكن":@"تم تعطيل الوضع الداكن");}
- (void)action:(UIButton *)b{NSString *t=b.titleLabel.text;if([t containsString:@"السجل"]){[[NSUserDefaults standardUserDefaults]removeObjectForKey:@"DGLog"];DGLog(@"تم مسح سجل DeltaGuard");}else if([t containsString:@"كاش"]){NSString *p=NSSearchPathForDirectoriesInDomains(NSCachesDirectory,NSUserDomainMask,YES).firstObject;for(NSString *f in [[NSFileManager defaultManager]contentsOfDirectoryAtPath:p error:nil])[[NSFileManager defaultManager]removeItemAtPath:[p stringByAppendingPathComponent:f] error:nil];DGLog(@"تم مسح كاش DeltaGuard");}else{NSString *msg=[t containsString:@"البيئة"]?[[DGEnvironment() description] stringByReplacingOccurrencesOfString:@";" withString:@"\n"]:@"هذه النسخة تستخدم واجهات iOS أصلية لفحص Rootless والتطبيقات المثبتة وتشغيل الخادم ومراقبة PID. لا يتم الادعاء بتنفيذ حقن أو تعديل ذاكرة دون محرك مخول.";UIAlertController *a=[UIAlertController alertControllerWithTitle:t message:msg preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"حسنًا" style:UIAlertActionStyleDefault handler:nil]];[self presentViewController:a animated:YES completion:nil];}}
@end

@implementation RootViewController
- (void)viewDidLoad{[super viewDidLoad];self.view.semanticContentAttribute=UISemanticContentAttributeForceRightToLeft;self.tabBar.semanticContentAttribute=UISemanticContentAttributeForceRightToLeft;self.view.backgroundColor=DGBackground();DGHomeViewController *home=[DGHomeViewController new];DGPermissionViewController *perm=[DGPermissionViewController new];DGServerViewController *server=[DGServerViewController new];DGSettingsViewController *settings=[DGSettingsViewController new];home.tabBarItem=[[UITabBarItem alloc]initWithTitle:@"الرئيسية" image:[UIImage systemImageNamed:@"house"] tag:0];perm.tabBarItem=[[UITabBarItem alloc]initWithTitle:@"الصلاحيات" image:[UIImage systemImageNamed:@"lock.shield"] tag:1];server.tabBarItem=[[UITabBarItem alloc]initWithTitle:@"الخوادم" image:[UIImage systemImageNamed:@"network"] tag:2];settings.tabBarItem=[[UITabBarItem alloc]initWithTitle:@"الإعدادات" image:[UIImage systemImageNamed:@"gear"] tag:3];self.viewControllers=@[home,perm,server,settings];self.tabBar.tintColor=DGPrimary();if(@available(iOS 13.0,*)){UITabBarAppearance *a=[UITabBarAppearance new];[a configureWithOpaqueBackground];a.backgroundColor=DGSurface();self.tabBar.standardAppearance=a;if(@available(iOS 15.0,*))self.tabBar.scrollEdgeAppearance=a;}}
@end
